      "title": "イギリスの茶の需要拡大",
      "body": [
        "こうして、<strong class=\"source-bold\">イギリス</strong>は中国との貿易でとんでもない赤字になった。当時、イギリスは大量の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">茶</strong></span>を<strong class=\"source-bold\">中国から輸入</strong>していた。しかも、18世紀末には労働者にまで砂糖入りの紅茶を飲む習慣が広がり、<strong class=\"source-bold\">茶の<ruby>需要<rt>じゅよう</rt></ruby>がどんどん拡大</strong>していたんだ。"
      ],
      "plainBody": [
        "こうして、イギリスは中国との貿易でとんでもない赤字になった。当時、イギリスは大量の茶を中国から輸入していた。しかも、18世紀末には労働者にまで砂糖入りの紅茶を飲む習慣が広がり、茶の需要がどんどん拡大していたんだ。"
      ],
