      "id": "modern-c02-l09-p01-040",
      "title": "大沽の攻撃と戦争の再開",
      "body": [
        "ちょっとした通知の不手際もあったんだけど、<strong class=\"source-bold\">清朝軍が<ruby>大沽<rt>タークー</rt></ruby></strong>で、批准のためにやってきた<strong class=\"source-bold\">英仏の使節を攻撃して戦争が再開</strong>した。"
      ],
      "plainBody": [
        "ちょっとした通知の不手際もあったんだけど、清朝軍が大沽で、批准のためにやってきた英仏の使節を攻撃して戦争が再開した。"
      ],
