      "title": "ヤークーブ＝ベクの新疆進出",
      "body": [
        "このあとロシアは<ruby>新疆<rt>しんきょう</rt></ruby>のムスリム反乱に乗じて、イリ地方にも進出してくる<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">➜P.138</strong></span>。きっかけは<strong class=\"source-bold\">新疆で起きたトルコ系ムスリム（ウイグル人）の反乱</strong>なんだけど、これに反応したコーカンド＝ハン国の将軍<strong class=\"source-bold\">ヤークーブ＝ベク</strong>は、「自分たちと同じトルコ系のムスリムがいる新疆で独立しよう！」と、<strong class=\"source-bold\">新疆に進出して独立政権を立てた</strong>んだ。"
      ],
