      "id": "modern-c02-l09-p02-006",
      "title": "上帝会の結成と広西の信徒",
      "body": [
        "この夢が聖書の抜粋と同じだったから、老人がヤハウェ（上帝）、兄がイエスと考え、「<strong class=\"source-bold\">自分は神の子、イエスの弟である</strong>」と称して、<strong class=\"source-bold\">キリスト教的な秘密結社上帝会</strong>を結成すると、<strong class=\"source-bold\"><ruby>広西<rt>こうせい</rt></ruby>省</strong>を中心に多くの信者を集めた。"
      ],
