      "id": "modern-c02-l09-p02-011",
      "title": "欧米の中立から清朝支援へ",
      "body": [
        "<strong class=\"source-bold\">太平天国が長江流域を制圧</strong>したのと同じころ、<strong class=\"source-bold\">第2次アヘン戦争が起きた</strong>よ。<strong class=\"source-bold\">欧米諸国</strong>は当初は<strong class=\"source-bold\">太平天国に対して中立</strong>を保って（清が太平天国の鎮圧で困るように「ほっといた」ってことね）戦争を有利に進めたけど、<strong class=\"source-bold\">戦後は清朝を助けて鎮圧に協力</strong>したよ。"
      ],
      "plainBody": [
        "太平天国が長江流域を制圧したのと同じころ、第2次アヘン戦争が起きたよ。欧米諸国は当初は太平天国に対して中立を保って（清が太平天国の鎮圧で困るように「ほっといた」ってことね）戦争を有利に進めたけど、戦後は清朝を助けて鎮圧に協力したよ。"
      ],
