      "id": "modern-c02-l09-p03-004",
      "title": "琉球の両属体制と明治政府",
      "body": [
        "こうして、<strong class=\"source-bold\">琉球</strong>は「<strong class=\"source-bold\">薩摩に征服された属国でありながら、清に朝貢する属国</strong>」という「<strong class=\"source-bold\">両属体制</strong>（両方の属国）」になった。そして、<strong class=\"source-bold\">明治<ruby>維新<rt>いしん</rt></ruby></strong>で新政府ができると、<strong class=\"source-bold\">琉球はそのまま日本の属国</strong>になったんだけど、ここで問題になったのが、欧米諸国の進出に対抗した「<strong class=\"source-bold\">国境画定問題</strong>」なんだよ。"
      ],
      "plainBody": [
        "こうして、琉球は「薩摩に征服された属国でありながら、清に朝貢する属国」という「両属体制（両方の属国）」になった。そして、明治維新で新政府ができると、琉球はそのまま日本の属国になったんだけど、ここで問題になったのが、欧米諸国の進出に対抗した「国境画定問題」なんだよ。"
      ],
