      "id": "modern-c02-l09-p03-027",
      "title": "壬午軍乱と公使館焼き討ち",
      "body": [
        "これを知った<strong class=\"source-bold\">大院君</strong>も「今が大チャンス！」って思い、<strong class=\"source-bold\">攘夷派の軍人たちが大院君を擁立して挙兵し</strong>、<strong class=\"source-bold\">閔政権の有力者</strong>や<strong class=\"source-bold\">日本人を殺害</strong>したほか、<strong class=\"source-bold\">日本公使館を焼き討ちした</strong>。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">壬午軍乱</strong></span>だよ。"
      ],
      "plainBody": [
        "これを知った大院君も「今が大チャンス！」って思い、攘夷派の軍人たちが大院君を擁立して挙兵し、閔政権の有力者や日本人を殺害したほか、日本公使館を焼き討ちした。これが壬午軍乱だよ。"
      ],
