      "body": [
        "この時、東学の信者たちは「<ruby>逐洋斥倭<rt>ちくようせきわ</rt></ruby>（ヨーロッパと日本を<ruby>排斥<rt>はいせき</rt></ruby>する）」をスローガンにして、各地で集会などを開いたんだけど、政府に<ruby>弾圧<rt>だんあつ</rt></ruby>されて、不満が高まっていたんだ。"
      ],
