      "body": [
        "そして、ついに爆発する時がきた！ 1894年、東学の地方幹部だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>全琫準<rt>ぜんほうじゅん</rt></ruby></strong></span>の指導で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">甲午農民戦争</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東学（党）の乱</strong></span>】が起き、南部から北部へと一気に反乱が広がったんだ。"
      ],
