      "body": [
        "こうして<strong class=\"source-bold\">日本が勝利</strong>すると、1895年<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>下関<rt>しものせき</rt></ruby>条約</strong></span>が結ばれた。日本全権は首相の<strong class=\"source-bold\"><ruby>伊藤<rt>いとう</rt></ruby><ruby>博文<rt>ひろぶみ</rt></ruby></strong>、清朝全権は<strong class=\"source-bold\"><ruby>李鴻章<rt>りこうしょう</rt></ruby></strong>、どっちも<strong class=\"source-bold\">両国の最高実力者</strong>だね。"
      ],
