      "title": "欧米との近代外交と残る冊封体制",
      "body": [
        "最後に、<strong class=\"source-bold\"><ruby>日清<rt>にっしん</rt></ruby>戦争が東アジアにもたらした変化</strong>について話しておくよ。<ruby>乾隆帝<rt>けんりゅうてい</rt></ruby>の時代には朝貢を軸とする<strong class=\"source-bold\">冊封体制が完成</strong>し、中国皇帝を頂点とする国際体制にヨーロッパ諸国との貿易も組み込んだ。しかし、19世紀に入ると産業革命で強大化した欧米<ruby>列強<rt>れっきょう</rt></ruby>の進出が始まり、<strong class=\"source-bold\">アヘン戦争</strong>によって<ruby>清<rt>シン</rt></ruby>朝は<strong class=\"source-bold\">開国</strong>して、一気にイギリスの求める<strong class=\"source-bold\">自由貿易体制</strong>に組み込まれた。そして<strong class=\"source-bold\">第2次アヘン戦争</strong>によって、欧米諸国に対しては朝貢関係ではない<strong class=\"source-bold\">近代的な対等外交</strong>を強要されたんだけど、<strong class=\"source-bold\">アジア各国との関係では冊封体制が残っていた</strong>わけだ。"
      ],
      "plainBody": [
        "最後に、日清戦争が東アジアにもたらした変化について話しておくよ。乾隆帝の時代には朝貢を軸とする冊封体制が完成し、中国皇帝を頂点とする国際体制にヨーロッパ諸国との貿易も組み込んだ。しかし、19世紀に入ると産業革命で強大化した欧米列強の進出が始まり、アヘン戦争によって清朝は開国して、一気にイギリスの求める自由貿易体制に組み込まれた。そして第2次アヘン戦争によって、欧米諸国に対しては朝貢関係ではない近代的な対等外交を強要されたんだけど、アジア各国との関係では冊封体制が残っていたわけだ。"
      ],
