      "id": "modern-c02-l09-p04-016",
      "title": "琉球・ベトナム・朝鮮と冊封体制の崩壊",
      "body": [
        "ただ、1874年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">台湾出兵</strong></span>を根拠に日本が<ruby>琉球<rt>りゅうきゅう</rt></ruby>を領有して朝貢国の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">琉球</strong></span>を失い、1884年に始まる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>清仏<rt>しんふつ</rt></ruby>戦争</strong></span>に敗れて、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム</strong></span>の<ruby>宗主権<rt>そうしゅけん</rt></ruby>も失い、さらに1894年に<ruby>勃発<rt>ぼっぱつ</rt></ruby>した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日清戦争</strong></span>に敗れて、最後に残った朝貢国の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">朝鮮</strong></span>も失ったから、この時点で<strong class=\"source-bold\">清朝には朝貢国がなくなった</strong>んだよ。これが<strong class=\"source-bold\">冊封体制の崩壊</strong>だ。中国も近代的な国際関係に完全に組み込まれたんだね。"
      ],
      "plainBody": [
        "ただ、1874年の台湾出兵を根拠に日本が琉球を領有して朝貢国の琉球を失い、1884年に始まる清仏戦争に敗れて、ベトナムの宗主権も失い、さらに1894年に勃発した日清戦争に敗れて、最後に残った朝貢国の朝鮮も失ったから、この時点で清朝には朝貢国がなくなったんだよ。これが冊封体制の崩壊だ。中国も近代的な国際関係に完全に組み込まれたんだね。"
      ],
